package week_01;
import javax.swing.*;import java.awt.*;
public class frm_LichSu extends JFrame {private final JTable table=new JTable();private final JLabel status=new JLabel("Đang tải...");public frm_LichSu(){super("Lịch sử thao tác - SQLite");setDefaultCloseOperation(DISPOSE_ON_CLOSE);setSize(900,440);setLocationRelativeTo(null);JButton refresh=new JButton("Tải lại");refresh.addActionListener(e->load());JPanel top=new JPanel(new BorderLayout());top.add(new JLabel("LỊCH SỬ THAO TÁC - BẢNG HISTORY"),BorderLayout.CENTER);top.add(refresh,BorderLayout.EAST);add(top,BorderLayout.NORTH);add(new JScrollPane(table),BorderLayout.CENTER);add(status,BorderLayout.SOUTH);load();}private void load(){try{table.setModel(HistoryDao.load(50));status.setText("Đã tải "+table.getRowCount()+" dòng.");}catch(Exception e){status.setText("Chưa đọc được lịch sử: "+e.getMessage());}}}
